CREATE TABLE `categories` (`id` integer NULL PRIMARY KEY AUTOINCREMENT, `name` text NOT NULL, `description` text NULL);
CREATE TABLE `pets` (`id` integer NULL PRIMARY KEY AUTOINCREMENT, `category_id` integer NULL, `name` text NOT NULL, `sku` text NOT NULL, `price` real NOT NULL DEFAULT 0, `internal_notes` text NULL, `status` text NOT NULL DEFAULT 'available', `created_at` text NULL DEFAULT (datetime('now')), CONSTRAINT `0` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON UPDATE NO ACTION ON DELETE NO ACTION);
CREATE UNIQUE INDEX `pets_sku` ON `pets` (`sku`);
CREATE TABLE `owners` (`id` integer NULL PRIMARY KEY AUTOINCREMENT, `name` text NOT NULL, `email` text NOT NULL, `phone` text NULL, `created_at` text NULL DEFAULT (datetime('now')));
CREATE UNIQUE INDEX `owners_email` ON `owners` (`email`);
CREATE TABLE `adoptions` (`id` integer NULL PRIMARY KEY AUTOINCREMENT, `pet_id` integer NOT NULL, `owner_id` integer NOT NULL, `adopted_at` text NOT NULL DEFAULT (datetime('now')), `adoption_fee` real NOT NULL DEFAULT 0, `updated_by` text NULL, CONSTRAINT `0` FOREIGN KEY (`owner_id`) REFERENCES `owners` (`id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT `1` FOREIGN KEY (`pet_id`) REFERENCES `pets` (`id`) ON UPDATE NO ACTION ON DELETE NO ACTION);
CREATE TABLE `medical_records` (`id` integer NULL PRIMARY KEY AUTOINCREMENT, `pet_id` integer NOT NULL, `visit_date` text NOT NULL DEFAULT (date('now')), `diagnosis` text NOT NULL, `treatment` text NULL, `vet_name` text NULL, CONSTRAINT `0` FOREIGN KEY (`pet_id`) REFERENCES `pets` (`id`) ON UPDATE NO ACTION ON DELETE NO ACTION);
CREATE TABLE `legacy_inventory` (`id` integer NULL PRIMARY KEY AUTOINCREMENT, `item_name` text NULL, `old_sku` text NULL, `quantity` integer NULL DEFAULT 0);
CREATE TABLE `staff` (`id` integer NULL PRIMARY KEY AUTOINCREMENT, `name` text NOT NULL, `role` text NOT NULL DEFAULT 'associate', `hired_at` text NOT NULL DEFAULT (date('now')));
CREATE TABLE `reviews` (`id` integer NULL PRIMARY KEY AUTOINCREMENT, `pet_id` integer NOT NULL, `owner_id` integer NOT NULL, `rating` integer NOT NULL, `body` text NULL, `location_id` integer NULL, `created_at` text NULL DEFAULT (datetime('now')), CONSTRAINT `0` FOREIGN KEY (`location_id`) REFERENCES `locations` (`id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT `1` FOREIGN KEY (`owner_id`) REFERENCES `owners` (`id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT `2` FOREIGN KEY (`pet_id`) REFERENCES `pets` (`id`) ON UPDATE NO ACTION ON DELETE NO ACTION);
